47	static int soc_platform_set_mb_irq(u32 devid, u32 tsid)
48	{
49	    struct res_inst_info inst;
50	    int ret;
51	    u32 irq, irq_request;
52	
53	    soc_resmng_inst_pack(&inst, devid, TS_SUBSYS, tsid);
54	
55	    ret = soc_resmng_set_irq_num(&inst, TS_MAILBOX_ACK_IRQ, 1);
56	    if (ret != 0) {
57	        soc_err("Set irq_num failed. (devid=%u; tsid=%u)\n", devid, tsid);
58	        return ret;
59	    }
60	
61	    ret = devdrv_get_ts_drv_irq_vector_id(devid, 0, &irq);
62	    if (ret != 0) {
63	        soc_err("Get mb irq failed. (devid=%u; tsid=%u)\n", devid, tsid);
64	        return ret;
65	    }
66	
67	    ret = devdrv_get_irq_vector(devid, irq, &irq_request);
68	    if (ret != 0) {
69	        soc_err("Get mb irq vector failed. (devid=%u; tsid=%u)\n", devid, tsid);
70	        return ret;
71	    }
72	
73	    ret = soc_resmng_set_irq_by_index(&inst, TS_MAILBOX_ACK_IRQ, 0, irq_request);
74	    if (ret != 0) {
75	        soc_err("Set irq failed. (devid=%u; tsid=%u)\n", devid, tsid);
76	        return ret;
77	    }
78	
79	    ret = soc_resmng_set_hwirq(&inst, TS_MAILBOX_ACK_IRQ, irq_request, irq);
80	    if (ret != 0) {
81	        soc_err("Set irq failed. (devid=%u; tsid=%u)\n", devid, tsid);
82	        return ret;
83	    }
84	
85	    return 0;
86	}
