129	#define CQ_UPDATE_IRQ_NUM 16
130	#define VDEV_START_ID 100
131	static void soc_platform_get_cq_update_irq_num(u32 devid, u32 *irq_num)
132	{
133	    if (devid < VDEV_START_ID) {
134	        if ((devdrv_get_connect_protocol(devid) == CONNECT_PROTOCOL_HCCS) &&
135	            (devdrv_is_mdev_vm_boot_mode(devid) == true)) {
136	            *irq_num = CQ_UPDATE_IRQ_NUM / 8; /* num is two, 8 is a divisor */
137	        } else {
138	            *irq_num = CQ_UPDATE_IRQ_NUM;
139	        }
140	    } else {
141	        if (devdrv_get_connect_protocol(devid) == CONNECT_PROTOCOL_HCCS) {
142	            *irq_num = CQ_UPDATE_IRQ_NUM / 8; /* num is two, 8 is a divisor */
143	        } else {
144	            *irq_num = CQ_UPDATE_IRQ_NUM / 2; /* num is eight, 2 is a divisor */
145	        }
146	    }
147	}
