149	static int soc_platform_set_cq_update_irq(u32 devid, u32 tsid)
150	{
151	    struct res_inst_info inst;
152	    int ret, i, index;
153	    u32 irq, irq_request;
154	    int irq_num;
155	
156	    soc_platform_get_cq_update_irq_num(devid, &irq_num);
157	    soc_resmng_inst_pack(&inst, devid, TS_SUBSYS, tsid);
158	
159	    soc_debug("Set irq_num. (devid=%u; tsid=%u; irq_num=%u)\n", devid, tsid, irq_num);
160	    ret = soc_resmng_set_irq_num(&inst, TS_CQ_UPDATE_IRQ, irq_num);
161	    if (ret != 0) {
162	        soc_err("Set irq_num failed. (devid=%u; tsid=%u)\n", devid, tsid);
163	        return ret;
164	    }
165	
166	    index = 2; /* cq update start from 2 */
167	    for (i = 0; i < irq_num; i++, index++) {
168	        ret = devdrv_get_ts_drv_irq_vector_id(devid, index, &irq);
169	        if (ret != 0) {
170	            soc_err("Get mb irq failed. (devid=%u; tsid=%u)\n", devid, tsid);
171	            return ret;
172	        }
173	
174	        ret = devdrv_get_irq_vector(devid, irq, &irq_request);
175	        if (ret != 0) {
176	            soc_err("Get mb irq vector failed. (devid=%u; tsid=%u)\n", devid, tsid);
177	            return ret;
178	        }
179	
180	        ret = soc_resmng_set_irq_by_index(&inst, TS_CQ_UPDATE_IRQ, i, irq_request);
181	        if (ret != 0) {
182	            soc_err("Set irq failed. (devid=%u; tsid=%u; index=%d; irq=%u)\n", devid, tsid, i, irq_request);
183	            return ret;
184	        }
185	
186	        ret = soc_resmng_set_hwirq(&inst, TS_CQ_UPDATE_IRQ, irq_request, irq);
187	        if (ret != 0) {
188	            soc_err("Set irq failed. (devid=%u; tsid=%u)\n", devid, tsid);
189	            return ret;
190	        }
191	    }
192	
193	    return 0;
194	}
