196	static int soc_platform_set_func_cq_irq(u32 devid, u32 tsid)
197	{
198	    struct res_inst_info inst;
199	    u32 irq, irq_request;
200	    int cq_irq_num;
201	    int ret;
202	
203	    soc_platform_get_cq_update_irq_num(devid, &cq_irq_num);
204	    ret = devdrv_get_ts_drv_irq_vector_id(devid, cq_irq_num + 2, &irq); /* use msi-x index 16 + 2 in phy */
205	    if (ret != 0) {
206	        soc_info("Not support func cq irq. (devid=%u; tsid=%u)\n", devid, tsid);
207	        return 0;
208	    }
209	
210	    ret = devdrv_get_irq_vector(devid, irq, &irq_request);
211	    if (ret != 0) {
212	        soc_err("Get func irq vector failed. (devid=%u; tsid=%u)\n", devid, tsid);
213	        return ret;
214	    }
215	
216	    soc_resmng_inst_pack(&inst, devid, TS_SUBSYS, tsid);
217	    ret = soc_resmng_set_irq_num(&inst, TS_FUNC_CQ_IRQ, 1);
218	    if (ret != 0) {
219	        soc_err("Set func irq_num failed. (devid=%u; tsid=%u)\n", devid, tsid);
220	        return ret;
221	    }
222	
223	    ret = soc_resmng_set_irq_by_index(&inst, TS_FUNC_CQ_IRQ, 0, irq_request);
224	    if (ret != 0) {
225	        soc_err("Set func irq failed. (devid=%u; tsid=%u)\n", devid, tsid);
226	        return ret;
227	    }
228	
229	    ret = soc_resmng_set_hwirq(&inst, TS_FUNC_CQ_IRQ, irq_request, irq);
230	    if (ret != 0) {
231	        soc_err("Set func irq failed. (devid=%u; tsid=%u)\n", devid, tsid);
232	        return ret;
233	    }
234	
235	    soc_info("Set func cq irq success. (devid=%u; tsid=%u)\n", devid, tsid);
236	
237	    return 0;
238	}
