292	static int soc_platform_set_reg_base(u32 devid, u32 tsid)
293	{
294	    struct res_inst_info inst;
295	    struct soc_reg_base_info io_base;
296	    int ret;
297	
298	    soc_resmng_inst_pack(&inst, devid, TS_SUBSYS, tsid);
299	
300	    ret = devdrv_get_addr_info(devid, DEVDRV_ADDR_TS_DOORBELL, 0, (u64 *)&io_base.io_base, &io_base.io_base_size);
301	    if (ret != 0) {
302	        soc_err("Get db addr failed. (devid=%u; tsid=%u)\n", devid, tsid);
303	        return ret;
304	    }
305	
306	    ret = soc_resmng_set_reg_base(&inst, "TS_DOORBELL_REG", &io_base);
307	    if (ret != 0) {
308	        soc_err("Set reg failed. (devid=%u; tsid=%u)\n", devid, tsid);
309	        return ret;
310	    }
311	
312	    ret = devdrv_get_addr_info(devid, DEVDRV_ADDR_STARS_SQCQ_BASE, 0, (u64 *)&io_base.io_base, &io_base.io_base_size);
313	    if (ret != 0) {
314	        soc_err("Get db addr failed. (devid=%u; tsid=%u)\n", devid, tsid);
315	        return ret;
316	    }
317	
318	    ret = soc_resmng_set_reg_base(&inst, "TS_STARS_RTSQ_SCHED_REG", &io_base);
319	    if (ret != 0) {
320	        soc_err("Set reg failed. (devid=%u; tsid=%u)\n", devid, tsid);
321	        return ret;
322	    }
323	
324	    ret = devdrv_get_addr_info(devid, DEVDRV_ADDR_STARS_SQCQ_INTR_BASE, 0, (u64 *)&io_base.io_base,
325	                               &io_base.io_base_size);
326	    if (ret != 0) {
327	        soc_err("Get stars sqcq int addr failed. (devid=%u; tsid=%u)\n", devid, tsid);
328	        return ret;
329	    }
330	
331	    ret = soc_resmng_set_reg_base(&inst, "TS_STARS_CQINT_REG", &io_base);
332	    if (ret != 0) {
333	        soc_err("Set reg failed. (devid=%u; tsid=%u)\n", devid, tsid);
334	        return ret;
335	    }
336	
337	    ret = devdrv_get_addr_info(devid, DEVDRV_ADDR_STARS_CDQM_BASE, 0, (u64 *)&io_base.io_base, &io_base.io_base_size);
338	    if (ret != 0) {
339	        soc_err("dev(%d) get addr info failed(%d).\n", devid, ret);
340	        return ret;
341	    }
342	
343	    ret = soc_resmng_set_reg_base(&inst, "TS_STARS_CDQM_REG", &io_base);
344	    if (ret != 0) {
345	        soc_err("Set reg failed. (devid=%u; tsid=%u)\n", devid, 0);
346	        return ret;
347	    }
348	
349	    ret = devdrv_get_addr_info(devid, DEVDRV_ADDR_STARS_INTR_BASE, 0, (u64 *)&io_base.io_base, &io_base.io_base_size);
350	    if (ret != 0) {
351	        soc_warn("Without stars intr. (devid=%u; ret=%d)\n", devid, ret);
352	    } else {
353	        ret = soc_resmng_set_reg_base(&inst, "TS_STARS_INT_REG", &io_base);
354	        if (ret != 0) {
355	            soc_err("Set reg failed. (devid=%u; tsid=%u)\n", devid, 0);
356	            return ret;
357	        }
358	    }
359	
360	    ret = devdrv_get_addr_info(devid, DEVDRV_ADDR_TS_NOTIFY_TBL_BASE, 0, (u64 *)&io_base.io_base,
361	                               &io_base.io_base_size);
362	    if (ret != 0) {
363	        soc_warn("Without notify table addr. (devid=%u; ret=%d)\n", devid, ret);
364	    } else {
365	        ret = soc_resmng_set_reg_base(&inst, "TS_STARS_NOTIFY_TBL_REG", &io_base);
366	        if (ret != 0) {
367	            soc_err("Set reg failed. (devid=%u; tsid=%u)\n", devid, 0);
368	            return ret;
369	        }
370	    }
371	
372	    ret = devdrv_get_addr_info(devid, DEVDRV_ADDR_TS_EVENT_TBL_NS_BASE, 0, (u64 *)&io_base.io_base,
373	                               &io_base.io_base_size);
374	    if (ret != 0) {
375	        soc_warn("Without event table addr. (devid=%u; ret=%d)\n", devid, ret);
376	    } else {
377	        ret = soc_resmng_set_reg_base(&inst, "TS_STARS_EVENT_TBL_NS_REG", &io_base);
378	        if (ret != 0) {
379	            soc_err("Set reg failed. (devid=%u; tsid=%u)\n", devid, 0);
380	            return ret;
381	        }
382	    }
383	
384	    return 0;
385	}
