387	static int soc_platform_set_rsv_mem(u32 devid, u32 tsid)
388	{
389	    struct res_inst_info inst;
390	    struct soc_rsv_mem_info rsv_mem;
391	    int ret;
392	
393	    soc_resmng_inst_pack(&inst, devid, TS_SUBSYS, tsid);
394	
395	    ret = devdrv_get_addr_info(devid, DEVDRV_ADDR_TS_SRAM, 0, (u64 *)&rsv_mem.rsv_mem, &rsv_mem.rsv_mem_size);
396	    if (ret == 0) {
397	        ret = soc_resmng_set_rsv_mem(&inst, "TS_SRAM_MEM", &rsv_mem);
398	        if (ret != 0) {
399	            soc_err("Set rsv_mem failed. (devid=%u; tsid=%u)\n", devid, tsid);
400	            return ret;
401	        }
402	    }
403	
404	    ret = devdrv_get_addr_info(devid, DEVDRV_ADDR_TS_SQ_BASE, 0, (u64 *)&rsv_mem.rsv_mem, &rsv_mem.rsv_mem_size);
405	    if (ret == 0) {
406	        ret = soc_resmng_set_rsv_mem(&inst, "TS_SQCQ_MEM", &rsv_mem);
407	        if (ret != 0) {
408	            soc_err("Set rsv_mem failed. (devid=%u; tsid=%u)\n", devid, tsid);
409	            return ret;
410	        }
411	    } else {
412	        soc_info("No ts sq addr. (devid=%u; tsid=%u)\n", devid, tsid);
413	    }
414	
415	    return 0;
416	}
417	
418	static int soc_platform_init_instance(u32 devid)
419	{
420	    u32 tsid;
421	    int ret;
422	
423	    tsid = 0;
424	    ret = soc_platform_set_irq(devid, tsid);
425	    ret |= soc_platform_set_reg_base(devid, tsid);
426	    ret |= soc_platform_set_rsv_mem(devid, tsid);
427	    ret |= soc_resmng_subsys_set_num(devid, TS_SUBSYS, 1);
428	
429	    return ret;
430	}
431	
432	#define SOC_PLATFORM_HOST_NOTIFIER "soc_platform"
433	static int soc_platform_host_notifier_func(u32 udevid, enum uda_notified_action action)
434	{
435	    int ret = 0;
436	
437	    if (action == UDA_INIT) {
438	        ret = soc_platform_init_instance(udevid);
439	    }
440	
441	    soc_info("notifier action. (udevid=%u; action=%d; ret=%d)\n", udevid, action, ret);
442	
443	    return ret;
444	}
445	
446	static int __ka_init soc_platform_init(void)
447	{
448	    struct uda_dev_type type;
449	    int ret;
450	    uda_davinci_near_real_entity_type_pack(&type);
451	    ret = uda_notifier_register(SOC_PLATFORM_HOST_NOTIFIER, &type, UDA_PRI0, soc_platform_host_notifier_func);
452	    if (ret != 0) {
453	        soc_err("Reg notifier failed. (ret=%d)\n", ret);
454	        return ret;
455	    }
456	
457	    uda_dev_type_pack(&type, UDA_DAVINCI, UDA_ENTITY, UDA_NEAR, UDA_REAL_SEC_EH);
458	    ret = uda_notifier_register(SOC_PLATFORM_HOST_NOTIFIER, &type, UDA_PRI0, soc_platform_host_notifier_func);
459	    if (ret != 0) {
460	        uda_davinci_near_real_entity_type_pack(&type);
461	        (void)uda_notifier_unregister(SOC_PLATFORM_HOST_NOTIFIER, &type);
462	        soc_err("Reg sec eh notifier failed. (ret=%d)\n", ret);
463	        return ret;
464	    }
465	
466	    return 0;
467	}
468	ka_module_init(soc_platform_init);
469	
470	static void __ka_exit soc_platform_exit(void)
471	{
472	    struct uda_dev_type type;
473	
474	    uda_davinci_near_real_entity_type_pack(&type);
475	    (void)uda_notifier_unregister(SOC_PLATFORM_HOST_NOTIFIER, &type);
476	    uda_dev_type_pack(&type, UDA_DAVINCI, UDA_ENTITY, UDA_NEAR, UDA_REAL_SEC_EH);
477	    (void)uda_notifier_unregister(SOC_PLATFORM_HOST_NOTIFIER, &type);
478	}
479	ka_module_exit(soc_platform_exit);
480	
